package com.dormrepair.file.service;import com.dormrepair.config.MinioProperties;import io.minio.*;import org.springframework.boot.ApplicationArguments;import org.springframework.boot.ApplicationRunner;import org.springframework.stereotype.Component;
@Component public class MinioBucketInitializer implements ApplicationRunner {private final MinioClient client;private final MinioProperties props;public MinioBucketInitializer(MinioClient c,MinioProperties p){client=c;props=p;}public void run(ApplicationArguments a)throws Exception{if(Boolean.TRUE.equals(props.autoCreateBucket())&&!client.bucketExists(BucketExistsArgs.builder().bucket(props.bucketName()).build()))client.makeBucket(MakeBucketArgs.builder().bucket(props.bucketName()).build());}}
